1	export type Cell = [x: number, y: number];
2	
3	const isAdjacentOrEqual = (coordinate: number, other: number): boolean =>
4	  Math.abs(coordinate - other) <= 1;
5	
6	const isNeighbor = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
7	  isAdjacentOrEqual(x, otherX) &&
8	  isAdjacentOrEqual(y, otherY) &&
9	  !(x === otherX && y === otherY);
10	
11	const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
12	  liveCells.filter((other) => isNeighbor(cell, other)).length;
13	
14	const survives = (cell: Cell, liveCells: Cell[]): boolean => {
15	  const liveNeighbors = countLiveNeighbors(cell, liveCells);
16	  return liveNeighbors === 2 || liveNeighbors === 3;
17	};
18	
19	export const nextGeneration = (liveCells: Cell[]): Cell[] =>
20	  liveCells.filter((cell) => survives(cell, liveCells));
